```python
import os
from typing import Dict, List, Optional, Tuple
from dataclasses import dataclass

from google.cloud import documentai
from google.cloud.documentai_v1 import Document


@dataclass
class ExtractedField:
    name: str
    value: str
    confidence: float
    normalized_value: Optional[str] = None


class InvoiceExtractionValidator:
    def __init__(self, project_id: str, location: str, processor_id: str):
        self.client = documentai.DocumentProcessorServiceClient()
        self.processor_name = self.client.processor_path(
            project_id, location, processor_id
        )

    def extract_invoice_fields(
        self, file_path: str, mime_type: str
    ) -> List[ExtractedField]:
        with open(file_path, "rb") as f:
            file_content = f.read()

        raw_document = documentai.RawDocument(
            content=file_content, mime_type=mime_type
        )
        request = documentai.ProcessRequest(
            name=self.processor_name, raw_document=raw_document
        )
        result = self.client.process_document(request=request)
        document = result.document

        extracted_fields = []
        for entity in document.entities:
            field = ExtractedField(
                name=entity.type_,
                value=entity.mention_text,
                confidence=entity.confidence,
                normalized_value=(
                    entity.normalized_value.text
                    if entity.normalized_value
                    else None
                ),
            )
            extracted_fields.append(field)

        return extracted_fields

    def validate_required_fields(
        self,
        extracted_fields: List[ExtractedField],
        required_fields: List[str],
        confidence_threshold: float = 0.8,
    ) -> Tuple[bool, Dict[str, ExtractedField], List[str]]:
        validation_results = {}
        missing_fields = []

        for field_name in required_fields:
            matching_fields = [
                f for f in extracted_fields if f.name == field_name
            ]
            if not matching_fields:
                missing_fields.append(field_name)
                continue

            best_field = max(matching_fields, key=lambda x: x.confidence)
            if best_field.confidence >= confidence_threshold:
                validation_results[field_name] = best_field
            else:
                missing_fields.append(
                    f"{field_name} (confidence: {best_field.confidence:.2f})"
                )

        is_valid = len(missing_fields) == 0
        return is_valid, validation_results, missing_fields


def main():
    project_id = os.getenv("GOOGLE_CLOUD_PROJECT")
    location = "us"  # Processor location
    processor_id = os.getenv("DOCUMENT_AI_PROCESSOR_ID")

    validator = InvoiceExtractionValidator(
        project_id=project_id,
        location=location,
        processor_id=processor_id,
    )

    invoice_path = "invoice.pdf"
    required_fields = [
        "invoice_id",
        "invoice_date",
        "due_date",
        "supplier_name",
        "total_amount",
    ]

    try:
        extracted_fields = validator.extract_invoice_fields(
            file_path=invoice_path, mime_type="application/pdf"
        )

        is_valid, validated_fields, missing_fields = (
            validator.validate_required_fields(
                extracted_fields=extracted_fields,
                required_fields=required_fields,
                confidence_threshold=0.75,
            )
        )

        print(f"Validation successful: {is_valid}")
        if is_valid:
            print("All required fields present with sufficient confidence:")
            for field_name, field in validated_fields.items():
                print(
                    f"  {field_name}: {field.value} "
                    f"(confidence: {field.confidence:.2f})"
                )
        else:
            print("Missing or low-confidence fields:")
            for missing in missing_fields:
                print(f"  - {missing}")

    except Exception as e:
        print(f"Error processing invoice: {e}")


if __name__ == "__main__":
    main()
